$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
$path = "C:\laragon\www\PPID\ppid-laravel\production_deployment\ppid_version2\jurnal.docx"
$doc = $word.Documents.Open($path, $false, $false)

$newText = "Era revolusi industri 4.0 dan transformasi digital telah membawa perubahan fundamental dalam berbagai dimensi kehidupan, tak terkecuali dalam mekanisme penyelenggaraan pemerintahan. Konsep tata kelola pemerintahan berbasis elektronik atau yang lebih dikenal dengan istilah e-Government kini telah menjadi salah satu instrumen utama dalam mengukur keberhasilan reformasi birokrasi di suatu daerah. Esensi tertinggi dari implementasi e-Government bukan hanya sebatas digitalisasi dokumen, melainkan upaya strategis untuk mewujudkan asas good governance (tata kelola pemerintahan yang baik). Melalui pemanfaatan teknologi informasi dan komunikasi (TIK), pemerintah diharapkan mampu menghadirkan layanan publik yang lebih responsif, serta menjamin ketersediaan akses informasi yang sangat transparan dan akuntabel guna menumbuhkan tingkat kepercayaan masyarakat (public trust).`r`rTransparansi informasi ini sejalan dengan mandat konstitusi yang tertuang dalam Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik (KIP). Undang-undang ini mewajibkan setiap badan publik, baik di tingkat pusat maupun daerah, untuk menyediakan, memberikan, dan/atau menerbitkan informasi publik yang berada di bawah kewenangannya kepada setiap pemohon informasi. Pemenuhan hak atas informasi ini harus dilakukan secara cepat, tepat waktu, berbiaya ringan, dan dengan cara yang sederhana. Untuk merealisasikan amanat undang-undang tersebut secara sistematis, struktur Pejabat Pengelola Informasi dan Dokumentasi (PPID) dibentuk sebagai garda terdepan dalam pelayanan informasi pemerintahan. Di era digital saat ini, PPID dituntut untuk tidak lagi bergantung pada loket fisik, melainkan harus beralih menggunakan portal sistem informasi terpadu yang dapat diakses oleh masyarakat kapan saja dan di mana saja.`r`rDalam konteks Pemerintah Kabupaten Sinjai, Dinas Komunikasi Informatika dan Persandian (Diskominfo) mengambil peran sentral sebagai PPID Utama. Diskominfo memiliki tanggung jawab krusial untuk menghimpun, mengelola, memverifikasi, hingga mempublikasikan seluruh ragam data informasi yang berasal dari puluhan Organisasi Perangkat Daerah (OPD) yang berstatus sebagai PPID Pembantu. Agar sinergi antara PPID Utama dan PPID Pembantu ini dapat berjalan lancar, dibutuhkan sebuah wadah digital yang sangat mumpuni. Menyadari tingginya volume aliran data dokumen publik yang harus dikelola setiap harinya, Diskominfo Kabupaten Sinjai secara proaktif telah mengimplementasikan langkah optimalisasi dan pengembangan skala besar pada aplikasi PPID berbasis web yang mereka miliki.`r`rOptimalisasi sistem ini bukan tanpa alasan, melainkan dipicu oleh urgensi untuk mengatasi berbagai kendala teknis dan birokratis pada sistem pendahulu. Berdasarkan hasil tinjauan awal, sistem PPID versi sebelumnya teridentifikasi memiliki kelemahan-kelemahan struktural yang cukup mendasar. Proses klasifikasi dan pengkategorian dokumen (seperti informasi berkala, informasi serta-merta, atau informasi setiap saat) masih bergantung pada intervensi manual yang sangat rentan terhadap kesalahan manusia (human error). Selain itu, ketiadaan fitur verifikasi otomatis terkait kelengkapan atribut dan batas ukuran berkas (file) sering kali menyebabkan dokumen gagal dipublikasikan ke server pusat. Lebih jauh lagi, antarmuka pengguna (user interface) pada sistem lama dinilai terlalu kaku dan tidak responsif. Akumulasi dari masalah-masalah teknis tersebut pada akhirnya sering kali menimbulkan bottleneck (penumpukan beban kerja) di pihak PPID Utama dan menyita banyak waktu produktif para admin OPD dalam melakukan pelaporan rutin.`r`rUntuk merespons tantangan tersebut, website PPID hasil optimalisasi terbaru dirancang dengan filosofi arsitektur desentralisasi tugas. Sistem ini memberdayakan setiap admin pembantu di masing-masing instansi OPD agar dapat mengunggah, menyunting, dan mengelola dokumen informasi publik mereka secara mandiri (self-service). Sistem terbaru ini juga diklaim telah dibekali dengan modul otomatisasi pengkategorian data dan fitur verifikasi keamanan berkas yang jauh lebih mutakhir. Namun demikian, ketersediaan pembaruan teknologi tidak serta-merta menjamin keberhasilan implementasinya di lapangan. Paradoks teknologi sering kali menunjukkan bahwa secanggih apa pun sebuah sistem, ia akan ditinggalkan oleh penggunanya jika sulit untuk dioperasikan.`r`rMengingat para admin OPD selaku operator sistem memiliki latar belakang karakteristik demografi, tingkat literasi digital, serta rentang pengalaman operasional yang sangat bervariasi, sistem pemerintahan diwajibkan untuk mendesain antarmuka yang seintuitif mungkin. Jika sistem yang baru ini ternyata masih dinilai membingungkan, memiliki alur kerja (workflow) penginputan yang berbelit-belit, atau tidak ramah pengguna (user-friendly), maka tingkat partisipasi OPD dalam menyetorkan data publik akan kembali menurun. Kondisi tersebut sangat berisiko menghambat perwujudan transparansi publik dan pada akhirnya menurunkan indeks keterbukaan informasi di Kabupaten Sinjai. Oleh karena itu, pengujian terhadap tingkat ketergunaan (usability) menjadi tahapan evaluasi yang tidak boleh dilewatkan.`r`rBeberapa penelitian terdahulu di bidang Sistem Informasi membuktikan bahwa faktor usability merupakan penentu krusial dalam keberhasilan adopsi sistem e-Government secara berkelanjutan. Untuk menghasilkan evaluasi yang mendalam dan tidak bias, penelitian ini mengadopsi kerangka analisis ganda, yaitu pendekatan standar metrik kelayakan ISO 9241-11 yang dikolaborasikan dengan landasan teori Technology Acceptance Model (TAM) cetusan Davis (1989). Standar ISO 9241-11 digunakan sebagai pisau bedah teknis untuk mengukur interaksi fisik operasional melalui tiga variabel utama, yakni efektivitas keberhasilan sistem, efisiensi waktu pengerjaan, dan tingkat kepuasan pengguna saat melihat antarmuka. Di sisi lain, kerangka kerja TAM difungsikan untuk membedah aspek psikologis penerimaan sistem melalui persepsi kemudahan (perceived ease of use) dan persepsi kebermanfaatan (perceived usefulness), guna melihat sejauh mana optimalisasi aplikasi PPID ini berdampak nyata pada lonjakan produktivitas kerja harian para admin.`r`rBerdasarkan penjabaran masalah dan argumentasi teoritis di atas, penelitian ini secara spesifik bertujuan untuk menganalisis dan mengukur tingkat keberhasilan usability pada dashboard website PPID Kabupaten Sinjai secara empiris, berdasarkan pengalaman nyata dari para admin OPD selaku aktor utama pelaporan data. Temuan dan hasil evaluasi dari penelitian ini tidak hanya ditujukan untuk memberikan potret statistik atas kinerja sistem, melainkan diharapkan mampu menjadi sumbangsih rujukan ilmiah serta rekomendasi teknis yang konkret bagi tim pengembang (developer) Diskominfo Kabupaten Sinjai dalam menyempurnakan fitur-fitur layanan di masa mendatang."

for ($i = 1; $i -le $doc.Paragraphs.Count; $i++) {
    $text = $doc.Paragraphs.Item($i).Range.Text
    if ($text -match "^1\. PENDAHULUAN") {
        # The next paragraph is the first body paragraph of Pendahuluan
        $p = $doc.Paragraphs.Item($i + 1)
        
        # Replace the first body paragraph with all 8 new paragraphs separated by carriage return
        $p.Range.Text = $newText
        
        # Now delete the remaining 3 old body paragraphs
        # since we replaced item $i+1, the next old paragraph is now at $i+2
        $doc.Paragraphs.Item($i + 2).Range.Delete()
        $doc.Paragraphs.Item($i + 2).Range.Delete()
        $doc.Paragraphs.Item($i + 2).Range.Delete()
        
        break
    }
}

$doc.Save()
$doc.Close()
$word.Quit()
[System.Runtime.Interopservices.Marshal]::ReleaseComObject($word) | Out-Null
Write-Host "Done updating Pendahuluan"
